.venv/bin/python - <<'PY'
import json, statistics, time, urllib.request
import serial
p='/dev/cu.usbserial-1130'
h=serial.Serial(p,115200,timeout=0.1,write_timeout=1); h.dtr=False; h.rts=False
end=time.monotonic()+135; raw=bytearray(); status_sent=False
while time.monotonic()<end:
    n=h.in_waiting
    if n: raw.extend(h.read(n))
    if not status_sent and end-time.monotonic()<20:
        h.write(b'status\n'); h.flush(); status_sent=True
    time.sleep(0.05)
if status_sent:
    time.sleep(2); n=h.in_waiting
    if n: raw.extend(h.read(n))
h.close(); text=raw.decode(errors='replace')
print('STAGE28E_B_HW_V3_SERIAL_CHARS',len(text)); print(text[-30000:])
crumbs=[x for x in text.splitlines() if 'stage28e_breadcrumb previous_valid=' in x]
valid=[x for x in crumbs if 'previous_valid=1' in x]
heartbeats=[x for x in text.splitlines() if 'heartbeat seq=' in x]
heap_ok=[x for x in text.splitlines() if 'heap_integrity_ok check=' in x]
status=[x for x in text.splitlines() if x.startswith('status ')]
coredump=[x for x in text.splitlines() if 'stage28e_coredump present=' in x]
if not valid: raise SystemExit('missing valid RTC breadcrumb after software restart')
if len(heartbeats)<8: raise SystemExit('insufficient heartbeat evidence across restart')
if len(heap_ok)<2: raise SystemExit('missing heap integrity success across both boot instances')
if not status: raise SystemExit('missing post-restart status')
s=status[-1]
for token in ['firmware_sha=b43516a2adcd320b3da2b4ee9051e442cceb5c93','outputs=fake-locked','reset_reason=3','internal_free=','internal_min=','internal_largest=','psram_free=','psram_min=','psram_largest=','boot_id=']:
    if token not in s: raise SystemExit('missing status token '+token)
